def count(lst):
    result = 0
    for item in lst:
        if isinstance(item, bool):
            if item is True:
                result += 1
        elif isinstance(item, int):
            if item == 1:
                result += 1
            elif item == 0:
                continue
            else:
                raise TypeError("Invalid integer value: only 0 or 1 allowed")
        else:
            raise TypeError("Invalid element type: only bool or int allowed")
    return result

