def max_sub_array_sum(arr):
    max_ending_here = max_so_far = arr[0]
    for x in arr[1:]:
        max_ending_here = max(x, max_ending_here + x)
        max_so_far = max(max_so_far, max_ending_here)
    return max_so_far

def count_nums(arr):
    def digit_sum(n):
        s = str(abs(n))
        if not s:
            return 0
        # first digit signed
        first_digit = int(s[0])
        if n < 0:
            first_digit = -first_digit
        # sum remaining digits always positive
        rest_sum = sum(int(d) for d in s[1:])
        return first_digit + rest_sum

    count = 0
    for num in arr:
        if digit_sum(num) > 0:
            count += 1
    return count

def minPath(grid, k):
    from collections import deque

    N = len(grid)
    # Map value to coordinates for quick access if needed
    # But probably we don't need this, we just do BFS from all cells

    # Directions: up, down, left, right
    directions = [(-1,0),(1,0),(0,-1),(0,1)]

    # We want the lexicographically smallest path of length k.
    # Because we can revisit cells, we cannot prune by visited sets.
    # But values are unique, so lex order depends on the visited sequence of values.
    # We can do BFS layer by layer, holding all possible paths, and prune to keep only lex smallest prefixes.

    # To handle the lex order, at each step we keep track of the minimal path ending at each cell.
    # We can keep only the lex smallest path ending at each cell with length = current step.
    # Because the path length is fixed, and answer is unique, this approach is feasible.

    # Initialization: for length=1, the path is just the cell itself.
    # For each cell, store the path as a tuple of values.
    # At each step, for each cell, we will try to extend paths from neighbors.

    # We keep a dict: cell -> minimal path (tuple)
    prev_paths = {}
    for r in range(N):
        for c in range(N):
            prev_paths[(r,c)] = (grid[r][c],)

    for step in range(2, k+1):
        curr_paths = {}
        # For each cell, try to get minimal path by checking neighbors' prev_paths
        for r in range(N):
            for c in range(N):
                # Among neighbors, pick the lex smallest path and append current cell's value
                candidates = []
                for dr, dc in directions:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < N and 0 <= nc < N and (nr,nc) in prev_paths:
                        candidate_path = prev_paths[(nr,nc)] + (grid[r][c],)
                        candidates.append(candidate_path)
                if candidates:
                    min_path = min(candidates)
                    # Update curr_paths
                    if (r,c) not in curr_paths or min_path < curr_paths[(r,c)]:
                        curr_paths[(r,c)] = min_path
        prev_paths = curr_paths

    # After k steps, find the lex smallest path among all cells
    if k == 1:
        # Just return the minimal single cell value path
        min_path = min(prev_paths.values())
    else:
        min_path = min(prev_paths.values())

    return list(min_path)

def cycpattern_check(a, b):
    a_lower = a.lower()
    b_lower = b.lower()
    n = len(b_lower)
    if n == 0:
        return True
    # Generate all rotations of b
    for i in range(n):
        rotated = b_lower[i:] + b_lower[:i]
        if rotated in a_lower:
            return True
    return False

from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    groups = paren_string.split()
    depths = []
    for group in groups:
        max_depth = 0
        current_depth = 0
        for ch in group:
            if ch == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif ch == ')':
                current_depth -= 1
        depths.append(max_depth)
    return depths

def words_in_sentence(sentence):
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    words = sentence.split()
    prime_length_words = [w for w in words if is_prime(len(w))]
    return " ".join(prime_length_words)

